        const _s = std.fmt.allocPrint(_allocator, "{s}{s}\x1b[0m", .{ _term_ansi(color), msg }) catch return;
        defer _allocator.free(_s);
        _f.writeStreamingAll(_io, _s) catch {};
    } else {
        _f.writeStreamingAll(_io, msg) catch {};
