        defer _allocator.free(_s);
        _f.writeStreamingAll(_io, _s) catch {};
    } else {
        const _s = std.fmt.allocPrint(_allocator, "[{s:<5}] {s}\n", .{ level_str, msg }) catch return;
        defer _allocator.free(_s);
        _f.writeStreamingAll(_io, _s) catch {};
